import React, { useState, useEffect } from 'react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Textarea } from '@/components/ui/textarea';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { Badge } from '@/components/ui/badge';
import { Plus, Edit, Trash2, Save, Settings as SettingsIcon, Building, Users, CreditCard, Package, Tag, FileText } from 'lucide-react';
import { organizationService, authService, billingService, servicesService, settingsService } from '@/services/ServiceFactory';
import { useService, useServiceMutation } from '@/hooks/useService';
import { BillingSettings, ServiceItem, MasterDataItem } from '@/services/mockData';

const Settings = () => {
  // Get current user and organization using service hooks
  const {
    data: currentUser,
    loading: userLoading,
    error: userError
  } = useService(() => Promise.resolve(authService.getCurrentUser()));

  const {
    data: organization,
    loading: orgLoading,
    error: orgError,
    refresh: refreshOrganization
  } = useService(() => organizationService.getCurrentOrganization());

  // Get billing settings using service hook
  const {
    data: billingData,
    loading: billingLoading,
    error: billingError,
    refresh: refreshBilling
  } = useService(() => Promise.resolve(billingService.getBillingSettings()));

  // Get services using service hook
  const {
    data: services,
    loading: servicesLoading,
    error: servicesError,
    refresh: refreshServices
  } = useService(() => Promise.resolve(servicesService.getAllServices()));

  // Get all master data from settings service using hooks
  const {
    data: eventTypes,
    loading: eventTypesLoading,
    error: eventTypesError,
    refresh: refreshEventTypes
  } = useService(() => Promise.resolve(settingsService.getEventTypes()));

  const {
    data: imageCategories,
    loading: imageCategoriesLoading,
    error: imageCategoriesError,
    refresh: refreshImageCategories
  } = useService(() => Promise.resolve(settingsService.getImageCategories()));

  const {
    data: employees,
    loading: employeesLoading,
    error: employeesError,
    refresh: refreshEmployees
  } = useService(() => Promise.resolve(settingsService.getEmployees()));

  const {
    data: inventoryItems,
    loading: inventoryItemsLoading,
    error: inventoryItemsError,
    refresh: refreshInventoryItems
  } = useService(() => Promise.resolve(settingsService.getInventoryItems()));

  const {
    data: ticketCategories,
    loading: ticketCategoriesLoading,
    error: ticketCategoriesError,
    refresh: refreshTicketCategories
  } = useService(() => Promise.resolve(settingsService.getTicketCategories()));

  // Local state for form data
  const [orgData, setOrgData] = useState({
    name: '',
    contactPerson: '',
    contactNo: '',
    address: '',
    about: '',
    defaultDomain: '',
    customDomain: ''
  });

  const [billingFormData, setBillingFormData] = useState<BillingSettings>({
    companyName: '',
    gstNumber: '',
    address: '',
    taxPercentage: 18,
    hsnNumber: '',
    bankAccount: '',
    ifscNumber: '',
    bankName: ''
  });

  // Update local state when data is loaded
  useEffect(() => {
    if (organization) {
      setOrgData({
        name: organization.name,
        contactPerson: organization.contactPerson,
        contactNo: organization.contactNo,
        address: '', // Not available in Organization type
        about: '', // Not available in Organization type
        defaultDomain: organization.defaultDomain,
        customDomain: organization.customDomain || ''
      });
    }
  }, [organization]);

  useEffect(() => {
    if (billingData) {
      setBillingFormData(billingData);
    }
  }, [billingData]);

  // Mutation hooks
  const updateOrganizationMutation = useServiceMutation(
    (data: any) => Promise.resolve(organizationService.updateOrganization(organization?.id || '', data))
  );

  const updateBillingMutation = useServiceMutation(
    (data: BillingSettings) => Promise.resolve(billingService.updateBillingSettings(data))
  );

  const createServiceMutation = useServiceMutation(
    (data: Omit<ServiceItem, 'id'>) => Promise.resolve(servicesService.createService(data))
  );

  const updateServiceMutation = useServiceMutation(
    (data: { id: string; service: Omit<ServiceItem, 'id'> }) => 
      Promise.resolve(servicesService.updateService(data.id, data.service))
  );

  const deleteServiceMutation = useServiceMutation(
    (id: string) => Promise.resolve(servicesService.deleteService(id))
  );

  const addMasterDataMutation = useServiceMutation(
    (data: { type: string; name: string; charge?: number }) => 
      Promise.resolve(settingsService.addMasterData(data.type as any, data.name, data.charge || 0))
  );

  const deleteMasterDataMutation = useServiceMutation(
    (data: { type: string; id: string }) => 
      Promise.resolve(settingsService.deleteMasterData(data.type as any, data.id))
  );

  const [showAddDialog, setShowAddDialog] = useState(false);
  const [showServiceDialog, setShowServiceDialog] = useState(false);
  const [currentMasterType, setCurrentMasterType] = useState<'eventTypes' | 'imageCategories' | 'employees' | 'inventoryItems' | 'ticketCategories'>('eventTypes');
  const [newItem, setNewItem] = useState({ name: '', charge: 0 });
  const [newService, setNewService] = useState<Omit<ServiceItem, 'id'>>({
    name: '',
    hsnCode: '',
    taxPercentage: 18,
    basePrice: 0
  });
  const [editingService, setEditingService] = useState<ServiceItem | null>(null);

  const handleSaveOrganization = async () => {
    if (organization?.id) {
      await updateOrganizationMutation.execute(orgData);
      await refreshOrganization();
      console.log('Organization updated:', orgData);
    }
  };

  const handleSaveBilling = async () => {
    await updateBillingMutation.execute(billingFormData);
    await refreshBilling();
    console.log('Billing settings updated:', billingFormData);
  };

  const handleAddService = async () => {
    if (editingService) {
      await updateServiceMutation.execute({
        id: editingService.id,
        service: newService
      });
      setEditingService(null);
    } else {
      await createServiceMutation.execute(newService);
    }
    await refreshServices();
    setNewService({ name: '', hsnCode: '', taxPercentage: 18, basePrice: 0 });
    setShowServiceDialog(false);
  };

  const handleEditService = (service: ServiceItem) => {
    setNewService({
      name: service.name,
      hsnCode: service.hsnCode,
      taxPercentage: service.taxPercentage,
      basePrice: service.basePrice
    });
    setEditingService(service);
    setShowServiceDialog(true);
  };

  const handleDeleteService = async (id: string) => {
    await deleteServiceMutation.execute(id);
    await refreshServices();
  };

  const handleAddItem = async () => {
    if (newItem.name.trim()) {
      await addMasterDataMutation.execute({
        type: currentMasterType,
        name: newItem.name,
        charge: newItem.charge
      });
      
      // Refresh the appropriate data based on type
      switch (currentMasterType) {
        case 'eventTypes':
          await refreshEventTypes();
          break;
        case 'imageCategories':
          await refreshImageCategories();
          break;
        case 'employees':
          await refreshEmployees();
          break;
        case 'inventoryItems':
          await refreshInventoryItems();
          break;
        case 'ticketCategories':
          await refreshTicketCategories();
          break;
      }
      
      setNewItem({ name: '', charge: 0 });
      setShowAddDialog(false);
    }
  };

  const handleDeleteItem = async (id: string, type: string) => {
    await deleteMasterDataMutation.execute({ type, id });
    
    // Refresh the appropriate data based on type
    switch (type) {
      case 'eventTypes':
        await refreshEventTypes();
        break;
      case 'imageCategories':
        await refreshImageCategories();
        break;
      case 'employees':
        await refreshEmployees();
        break;
      case 'inventoryItems':
        await refreshInventoryItems();
        break;
      case 'ticketCategories':
        await refreshTicketCategories();
        break;
    }
  };

  const openAddDialog = (type: 'eventTypes' | 'imageCategories' | 'employees' | 'inventoryItems' | 'ticketCategories') => {
    setCurrentMasterType(type);
    setShowAddDialog(true);
  };

  const openAddServiceDialog = () => {
    setEditingService(null);
    setNewService({ name: '', hsnCode: '', taxPercentage: 18, basePrice: 0 });
    setShowServiceDialog(true);
  };

  // Loading state
  if (userLoading || orgLoading || billingLoading || servicesLoading) {
    return (
      <div className="space-y-6">
        <div className="animate-pulse">
          <div className="h-8 bg-gray-200 rounded w-1/4 mb-4"></div>
          <div className="space-y-3">
            {[...Array(5)].map((_, i) => (
              <div key={i} className="h-32 bg-gray-200 rounded"></div>
            ))}
          </div>
        </div>
      </div>
    );
  }

  // Error state
  if (userError || orgError || billingError || servicesError) {
    return (
      <div className="space-y-6">
        <div className="bg-red-50 border border-red-200 rounded-md p-4">
          <div className="flex">
            <div className="flex-shrink-0">
              <svg className="h-5 w-5 text-red-400" viewBox="0 0 20 20" fill="currentColor">
                <path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zM8.707 7.293a1 1 0 00-1.414 1.414L8.586 10l-1.293 1.293a1 1 0 101.414 1.414L10 11.414l1.293 1.293a1 1 0 001.414-1.414L11.414 10l1.293-1.293a1 1 0 00-1.414-1.414L10 8.586 8.707 7.293z" clipRule="evenodd" />
              </svg>
            </div>
            <div className="ml-3">
              <h3 className="text-sm font-medium text-red-800">
                Error loading settings
              </h3>
              <div className="mt-2 text-sm text-red-700">
                <p>{userError || orgError || billingError || servicesError}</p>
              </div>
            </div>
          </div>
        </div>
      </div>
    );
  }

  const MasterDataCard = ({ title, items, type }: { title: string, items: MasterDataItem[], type: string }) => (
    <Card>
      <CardHeader>
        <div className="flex justify-between items-center">
          <CardTitle className="text-lg">{title}</CardTitle>
          <Button size="sm" onClick={() => openAddDialog(type as any)}>
            <Plus className="h-4 w-4 mr-2" />
            Add
          </Button>
        </div>
      </CardHeader>
      <CardContent>
        <div className="space-y-2">
          {items?.map((item) => (
            <div key={item.id} className="flex justify-between items-center p-2 border rounded">
              <div>
                <span className="font-medium">{item.name}</span>
                {item.charge && <span className="text-sm text-gray-600 ml-2">₹{item.charge}</span>}
              </div>
              <Button
                size="sm"
                variant="outline"
                onClick={() => handleDeleteItem(item.id, type)}
              >
                <Trash2 className="h-4 w-4" />
              </Button>
            </div>
          ))}
        </div>
      </CardContent>
    </Card>
  );

  return (
    <div className="space-y-6">
      <div>
        <h1 className="text-3xl font-bold">Settings</h1>
        <p className="text-gray-600">Manage organization settings and master data</p>
      </div>

      <Tabs defaultValue="organization" className="space-y-4">
        <TabsList className="grid w-full grid-cols-8">
          <TabsTrigger value="organization">Organization</TabsTrigger>
          <TabsTrigger value="billing">Billing</TabsTrigger>
          <TabsTrigger value="services">Services</TabsTrigger>
          <TabsTrigger value="eventTypes">Event Types</TabsTrigger>
          <TabsTrigger value="imageCategories">Image Categories</TabsTrigger>
          <TabsTrigger value="employees">Employees</TabsTrigger>
          <TabsTrigger value="inventory">Inventory</TabsTrigger>
          <TabsTrigger value="ticketCategories">Ticket Categories</TabsTrigger>
        </TabsList>

        <TabsContent value="organization" className="space-y-4">
          <Card>
            <CardHeader>
              <CardTitle>Organization Information</CardTitle>
            </CardHeader>
            <CardContent className="space-y-4">
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <Label htmlFor="orgName">Organization Name</Label>
                  <Input
                    id="orgName"
                    value={orgData.name}
                    onChange={(e) => setOrgData(prev => ({ ...prev, name: e.target.value }))}
                  />
                </div>
                <div>
                  <Label htmlFor="contactPerson">Contact Person</Label>
                  <Input
                    id="contactPerson"
                    value={orgData.contactPerson}
                    onChange={(e) => setOrgData(prev => ({ ...prev, contactPerson: e.target.value }))}
                  />
                </div>
                <div>
                  <Label htmlFor="contactNo">Contact Number</Label>
                  <Input
                    id="contactNo"
                    value={orgData.contactNo}
                    onChange={(e) => setOrgData(prev => ({ ...prev, contactNo: e.target.value }))}
                  />
                </div>
                <div>
                  <Label htmlFor="address">Address</Label>
                  <Input
                    id="address"
                    value={orgData.address}
                    onChange={(e) => setOrgData(prev => ({ ...prev, address: e.target.value }))}
                  />
                </div>
              </div>
              
              <div>
                <Label htmlFor="about">About</Label>
                <Textarea
                  id="about"
                  value={orgData.about}
                  onChange={(e) => setOrgData(prev => ({ ...prev, about: e.target.value }))}
                  placeholder="Tell us about your organization"
                />
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div>
                  <Label htmlFor="defaultDomain">Default Domain</Label>
                  <Input
                    id="defaultDomain"
                    value={orgData.defaultDomain}
                    onChange={(e) => setOrgData(prev => ({ ...prev, defaultDomain: e.target.value }))}
                  />
                </div>
                <div>
                  <Label htmlFor="customDomain">Custom Domain</Label>
                  <Input
                    id="customDomain"
                    value={orgData.customDomain}
                    onChange={(e) => setOrgData(prev => ({ ...prev, customDomain: e.target.value }))}
                    placeholder="yourdomain.com"
                  />
                </div>
              </div>

              <Button onClick={handleSaveOrganization} className="w-full">
                <Save className="h-4 w-4 mr-2" />
                Save Organization Settings
              </Button>
            </CardContent>
          </Card>
        </TabsContent>

        <TabsContent value="billing" className="space-y-4">
          <Card>
            <CardHeader>
              <CardTitle>Billing Settings</CardTitle>
            </CardHeader>
            <CardContent className="space-y-4">
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <Label htmlFor="companyName">Company Name</Label>
                  <Input
                    id="companyName"
                    value={billingFormData.companyName}
                    onChange={(e) => setBillingFormData(prev => ({ ...prev, companyName: e.target.value }))}
                  />
                </div>
                <div>
                  <Label htmlFor="gstNumber">GST Number</Label>
                  <Input
                    id="gstNumber"
                    value={billingFormData.gstNumber}
                    onChange={(e) => setBillingFormData(prev => ({ ...prev, gstNumber: e.target.value }))}
                  />
                </div>
                <div className="col-span-2">
                  <Label htmlFor="billingAddress">Address</Label>
                  <Textarea
                    id="billingAddress"
                    value={billingFormData.address}
                    onChange={(e) => setBillingFormData(prev => ({ ...prev, address: e.target.value }))}
                  />
                </div>
                <div>
                  <Label htmlFor="taxPercentage">Tax Percentage</Label>
                  <Input
                    id="taxPercentage"
                    type="number"
                    value={billingFormData.taxPercentage}
                    onChange={(e) => setBillingFormData(prev => ({ ...prev, taxPercentage: parseFloat(e.target.value) }))}
                  />
                </div>
                <div>
                  <Label htmlFor="hsnNumber">HSN Number</Label>
                  <Input
                    id="hsnNumber"
                    value={billingFormData.hsnNumber}
                    onChange={(e) => setBillingFormData(prev => ({ ...prev, hsnNumber: e.target.value }))}
                  />
                </div>
                <div>
                  <Label htmlFor="bankAccount">Bank Account</Label>
                  <Input
                    id="bankAccount"
                    value={billingFormData.bankAccount}
                    onChange={(e) => setBillingFormData(prev => ({ ...prev, bankAccount: e.target.value }))}
                  />
                </div>
                <div>
                  <Label htmlFor="ifscNumber">IFSC Number</Label>
                  <Input
                    id="ifscNumber"
                    value={billingFormData.ifscNumber}
                    onChange={(e) => setBillingFormData(prev => ({ ...prev, ifscNumber: e.target.value }))}
                  />
                </div>
                <div>
                  <Label htmlFor="bankName">Bank Name</Label>
                  <Input
                    id="bankName"
                    value={billingFormData.bankName}
                    onChange={(e) => setBillingFormData(prev => ({ ...prev, bankName: e.target.value }))}
                  />
                </div>
              </div>

              <Button onClick={handleSaveBilling} className="w-full">
                <Save className="h-4 w-4 mr-2" />
                Save Billing Settings
              </Button>
            </CardContent>
          </Card>
        </TabsContent>

        <TabsContent value="services" className="space-y-4">
          <Card>
            <CardHeader>
              <div className="flex justify-between items-center">
                <CardTitle>Services Management</CardTitle>
                <Button onClick={openAddServiceDialog}>
                  <Plus className="h-4 w-4 mr-2" />
                  Add Service
                </Button>
              </div>
            </CardHeader>
            <CardContent>
              <div className="space-y-3">
                {services?.map((service) => (
                  <div key={service.id} className="flex justify-between items-center p-3 border rounded">
                    <div className="flex-1">
                      <div className="font-medium">{service.name}</div>
                      <div className="text-sm text-gray-600">
                        HSN: {service.hsnCode} | Tax: {service.taxPercentage}% | Price: ₹{service.basePrice}
                      </div>
                    </div>
                    <div className="flex gap-2">
                      <Button
                        size="sm"
                        variant="outline"
                        onClick={() => handleEditService(service)}
                      >
                        <Edit className="h-4 w-4" />
                      </Button>
                      <Button
                        size="sm"
                        variant="outline"
                        onClick={() => handleDeleteService(service.id)}
                      >
                        <Trash2 className="h-4 w-4" />
                      </Button>
                    </div>
                  </div>
                ))}
              </div>
            </CardContent>
          </Card>
        </TabsContent>

        <TabsContent value="eventTypes" className="space-y-4">
          <MasterDataCard title="Event Types" items={eventTypes || []} type="eventTypes" />
        </TabsContent>

        <TabsContent value="imageCategories" className="space-y-4">
          <MasterDataCard title="Image Categories" items={imageCategories || []} type="imageCategories" />
        </TabsContent>

        <TabsContent value="employees" className="space-y-4">
          <MasterDataCard title="Employees" items={employees || []} type="employees" />
        </TabsContent>

        <TabsContent value="inventory" className="space-y-4">
          <MasterDataCard title="Inventory Items" items={inventoryItems || []} type="inventoryItems" />
        </TabsContent>

        <TabsContent value="ticketCategories" className="space-y-4">
          <MasterDataCard title="Ticket Categories" items={ticketCategories || []} type="ticketCategories" />
        </TabsContent>
      </Tabs>

      {/* Add Item Dialog */}
      <Dialog open={showAddDialog} onOpenChange={setShowAddDialog}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>Add New Item</DialogTitle>
          </DialogHeader>
          <div className="space-y-4">
            <div>
              <Label htmlFor="itemName">Name</Label>
              <Input
                id="itemName"
                value={newItem.name}
                onChange={(e) => setNewItem(prev => ({ ...prev, name: e.target.value }))}
                placeholder="Enter name"
              />
            </div>
            {currentMasterType === 'inventoryItems' && (
              <div>
                <Label htmlFor="itemCharge">Rental Charge</Label>
                <Input
                  id="itemCharge"
                  type="number"
                  value={newItem.charge}
                  onChange={(e) => setNewItem(prev => ({ ...prev, charge: parseInt(e.target.value) }))}
                  placeholder="Enter rental charge"
                />
              </div>
            )}
            <Button onClick={handleAddItem} className="w-full">
              Add Item
            </Button>
          </div>
        </DialogContent>
      </Dialog>

      {/* Add/Edit Service Dialog */}
      <Dialog open={showServiceDialog} onOpenChange={setShowServiceDialog}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>{editingService ? 'Edit Service' : 'Add New Service'}</DialogTitle>
          </DialogHeader>
          <div className="space-y-4">
            <div>
              <Label htmlFor="serviceName">Service Name</Label>
              <Input
                id="serviceName"
                value={newService.name}
                onChange={(e) => setNewService(prev => ({ ...prev, name: e.target.value }))}
                placeholder="Enter service name"
              />
            </div>
            <div>
              <Label htmlFor="hsnCode">HSN Code</Label>
              <Input
                id="hsnCode"
                value={newService.hsnCode}
                onChange={(e) => setNewService(prev => ({ ...prev, hsnCode: e.target.value }))}
                placeholder="Enter HSN code"
              />
            </div>
            <div>
              <Label htmlFor="taxPercentage">Tax Percentage</Label>
              <Input
                id="taxPercentage"
                type="number"
                value={newService.taxPercentage}
                onChange={(e) => setNewService(prev => ({ ...prev, taxPercentage: parseFloat(e.target.value) }))}
                placeholder="Enter tax percentage"
              />
            </div>
            <div>
              <Label htmlFor="basePrice">Base Price</Label>
              <Input
                id="basePrice"
                type="number"
                value={newService.basePrice}
                onChange={(e) => setNewService(prev => ({ ...prev, basePrice: parseFloat(e.target.value) }))}
                placeholder="Enter base price"
              />
            </div>
            <Button onClick={handleAddService} className="w-full">
              {editingService ? 'Update Service' : 'Add Service'}
            </Button>
          </div>
        </DialogContent>
      </Dialog>
    </div>
  );
};

export default Settings;
