import React from 'react';
import { Card, CardContent } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { MapPin, Phone, Mail, Clock, Navigation, Building } from 'lucide-react';
import { organizationService } from '@/services/ServiceFactory';
import { useService } from '@/hooks/useService';

export function PublicFooter() {
  // Use service hook for async data fetching
  const {
    data: organization,
    loading: orgLoading,
    error: orgError
  } = useService(() => organizationService.getCurrentOrganization());

  // Show loading state
  if (orgLoading) {
    return (
      <footer className="bg-gray-900 text-white py-12">
        <div className="container mx-auto px-4">
          <div className="animate-pulse">
            <div className="h-6 bg-gray-700 rounded w-1/4 mb-4"></div>
            <div className="h-4 bg-gray-700 rounded w-1/2 mb-2"></div>
            <div className="h-4 bg-gray-700 rounded w-1/3"></div>
          </div>
        </div>
      </footer>
    );
  }

  // Show error state
  if (orgError || !organization) {
    return (
      <footer className="bg-gray-900 text-white py-12">
        <div className="container mx-auto px-4">
          <div className="text-center">
            <p>Unable to load organization information</p>
          </div>
        </div>
      </footer>
    );
  }

  return (
    <footer className="bg-gray-900 text-white py-12">
      <div className="container mx-auto px-4">
        <div className="grid grid-cols-1 md:grid-cols-4 gap-8">
          {/* Organization Info */}
          <div className="md:col-span-2">
            <div className="flex items-center mb-4">
              <Building className="h-8 w-8 mr-3" />
              <h3 className="text-xl font-bold">{organization.name}</h3>
            </div>
            <p className="text-gray-300 mb-4">Professional wedding and event venue services</p>
            <div className="space-y-2">
              <div className="flex items-center text-sm">
                <MapPin className="h-4 w-4 mr-2" />
                <span>123 Wedding Street, Event City, EC 12345</span>
              </div>
              <div className="flex items-center text-sm">
                <Phone className="h-4 w-4 mr-2" />
                <span>{organization.contactNo}</span>
              </div>
              <div className="flex items-center text-sm">
                <Mail className="h-4 w-4 mr-2" />
                <span>contact@{organization.defaultDomain}</span>
              </div>
            </div>
          </div>

          {/* Quick Links */}
          <div>
            <h4 className="text-lg font-semibold mb-4">Quick Links</h4>
            <ul className="space-y-2">
              <li>
                <Button variant="link" className="p-0 h-auto text-gray-300 hover:text-white">
                  About Us
                </Button>
              </li>
              <li>
                <Button variant="link" className="p-0 h-auto text-gray-300 hover:text-white">
                  Our Services
                </Button>
              </li>
              <li>
                <Button variant="link" className="p-0 h-auto text-gray-300 hover:text-white">
                  Contact
                </Button>
              </li>
              <li>
                <Button variant="link" className="p-0 h-auto text-gray-300 hover:text-white">
                  Privacy Policy
                </Button>
              </li>
            </ul>
          </div>

          {/* Business Hours */}
          <div>
            <h4 className="text-lg font-semibold mb-4">Business Hours</h4>
            <div className="space-y-2 text-sm">
              <div className="flex items-center">
                <Clock className="h-4 w-4 mr-2" />
                <span>Monday - Friday: 9:00 AM - 6:00 PM</span>
              </div>
              <div className="flex items-center">
                <Clock className="h-4 w-4 mr-2" />
                <span>Saturday: 10:00 AM - 4:00 PM</span>
              </div>
              <div className="flex items-center">
                <Clock className="h-4 w-4 mr-2" />
                <span>Sunday: Closed</span>
              </div>
            </div>
            
            <div className="mt-6">
              <Button className="w-full" size="sm">
                <Navigation className="h-4 w-4 mr-2" />
                Get Directions
              </Button>
            </div>
          </div>
        </div>

        <div className="border-t border-gray-800 mt-8 pt-8">
          <div className="flex flex-col md:flex-row justify-between items-center">
            <p className="text-gray-400 text-sm">
              © {new Date().getFullYear()} {organization.name}. All rights reserved.
            </p>
            <div className="flex space-x-4 mt-4 md:mt-0">
              <Badge variant="secondary">Wedding Venues</Badge>
              <Badge variant="secondary">Event Planning</Badge>
              <Badge variant="secondary">Catering Services</Badge>
            </div>
          </div>
        </div>
      </div>
    </footer>
  );
}
