import React from 'react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { customerClicksService } from '@/services/ServiceFactory';
import { useService } from '@/hooks/useService';
import { TrendingUp, Users, Calendar, Star } from 'lucide-react';

export function CustomerClicksSection() {
  // Get customer clicks using service hook
  const {
    data: customerClicks,
    loading: clicksLoading,
    error: clicksError
  } = useService(() => Promise.resolve(customerClicksService.getAll()));

  // Loading state
  if (clicksLoading) {
    return (
      <section className="py-12 bg-gray-50">
        <div className="container mx-auto px-4">
          <div className="animate-pulse">
            <div className="h-8 bg-gray-200 rounded w-1/4 mb-8"></div>
            <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
              {[...Array(4)].map((_, i) => (
                <div key={i} className="h-32 bg-gray-200 rounded"></div>
              ))}
            </div>
          </div>
        </div>
      </section>
    );
  }

  // Error state
  if (clicksError || !customerClicks) {
    return null;
  }

  // Calculate metrics
  const totalClicks = customerClicks.length;
  const uniqueUsers = new Set(customerClicks.map(click => click.customerId)).size;
  const todayClicks = customerClicks.filter(click => {
    const clickDate = new Date(click.timestamp);
    const today = new Date();
    return clickDate.toDateString() === today.toDateString();
  }).length;

  const averageRating = customerClicks.length > 0 
    ? customerClicks.reduce((sum, click) => sum + (click.rating || 0), 0) / customerClicks.length 
    : 0;

  return (
    <section className="py-12 bg-gray-50">
      <div className="container mx-auto px-4">
        <div className="text-center mb-12">
          <h2 className="text-3xl font-bold text-gray-900 mb-4">Customer Engagement</h2>
          <p className="text-lg text-gray-600 max-w-2xl mx-auto">
            Track how customers interact with our platform and services
          </p>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
          <Card>
            <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
              <CardTitle className="text-sm font-medium">Total Clicks</CardTitle>
              <TrendingUp className="h-4 w-4 text-blue-500" />
            </CardHeader>
            <CardContent>
              <div className="text-2xl font-bold text-blue-600">{totalClicks}</div>
              <p className="text-xs text-muted-foreground">
                All time interactions
              </p>
            </CardContent>
          </Card>

          <Card>
            <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
              <CardTitle className="text-sm font-medium">Unique Users</CardTitle>
              <Users className="h-4 w-4 text-green-500" />
            </CardHeader>
            <CardContent>
              <div className="text-2xl font-bold text-green-600">{uniqueUsers}</div>
              <p className="text-xs text-muted-foreground">
                Individual customers
              </p>
            </CardContent>
          </Card>

          <Card>
            <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
              <CardTitle className="text-sm font-medium">Today's Clicks</CardTitle>
              <Calendar className="h-4 w-4 text-orange-500" />
            </CardHeader>
            <CardContent>
              <div className="text-2xl font-bold text-orange-600">{todayClicks}</div>
              <p className="text-xs text-muted-foreground">
                Today's interactions
              </p>
            </CardContent>
          </Card>

          <Card>
            <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
              <CardTitle className="text-sm font-medium">Average Rating</CardTitle>
              <Star className="h-4 w-4 text-purple-500" />
            </CardHeader>
            <CardContent>
              <div className="text-2xl font-bold text-purple-600">{averageRating.toFixed(1)}</div>
              <p className="text-xs text-muted-foreground">
                Customer satisfaction
              </p>
            </CardContent>
          </Card>
        </div>
      </div>
    </section>
  );
}
