import React, { useState } from 'react';
import { Calendar } from '@/components/ui/calendar';
import { Button } from '@/components/ui/button';
import { Sun, Moon, X } from 'lucide-react';
import { format } from 'date-fns';
import { bookingService } from '@/services/ServiceFactory';
import { useService } from '@/hooks/useService';
import { cn } from '@/lib/utils';

interface HallDetailCalendarProps {
  hallId: string;
  onDateSelect: (date: Date | null) => void;
  selectedDate: Date | null;
}

export function HallDetailCalendar({ hallId, onDateSelect, selectedDate }: HallDetailCalendarProps) {
  // Get hall bookings using service hook
  const {
    data: hallBookings,
    loading: bookingsLoading,
    error: bookingsError
  } = useService(() => bookingService.getBookingsByHall(hallId));

  const getBookingStatus = (date: Date) => {
    if (!hallBookings) return 'available';
    
    const dateStr = format(date, 'yyyy-MM-dd');
    const dayBookings = hallBookings.filter(booking => 
      booking.eventDate === dateStr && 
      (booking.status === 'confirmed' || booking.status === 'active')
    );

    const hasFullDay = dayBookings.some(b => b.timeSlot === 'fullday');
    const hasMorning = dayBookings.some(b => b.timeSlot === 'morning');
    const hasEvening = dayBookings.some(b => b.timeSlot === 'evening');

    if (hasFullDay || (hasMorning && hasEvening)) {
      return 'full';
    } else if (hasMorning) {
      return 'morning-booked';
    } else if (hasEvening) {
      return 'evening-booked';
    }
    return 'available';
  };

  const handleDateSelect = (date: Date | undefined) => {
    if (!date) {
      onDateSelect(null);
      return;
    }
    
    const status = getBookingStatus(date);
    if (status === 'full') {
      return; // Can't select fully booked days
    }
    
    onDateSelect(date);
  };

  const renderDay = (day: Date) => {
    const status = getBookingStatus(day);
    const dayNumber = day.getDate();
    const isSelected = selectedDate && format(selectedDate, 'yyyy-MM-dd') === format(day, 'yyyy-MM-dd');
    
    return (
      <div className={cn(
        "relative w-full h-full flex flex-col items-center justify-center p-1 rounded-md cursor-pointer",
        isSelected && "bg-primary text-primary-foreground",
        status === 'full' && "opacity-50 cursor-not-allowed"
      )}>
        <span className="text-sm font-medium">{dayNumber}</span>
        <div className="flex gap-1 mt-1">
          {status === 'full' && (
            <X className="h-2 w-2 text-red-500" />
          )}
          {status === 'morning-booked' && (
            <>
              <X className="h-1.5 w-1.5 text-red-400" />
              <Moon className="h-1.5 w-1.5 text-green-500" />
            </>
          )}
          {status === 'evening-booked' && (
            <>
              <Sun className="h-1.5 w-1.5 text-green-500" />
              <X className="h-1.5 w-1.5 text-red-400" />
            </>
          )}
          {status === 'available' && (
            <>
              <Sun className="h-1.5 w-1.5 text-green-500" />
              <Moon className="h-1.5 w-1.5 text-green-500" />
            </>
          )}
        </div>
      </div>
    );
  };

  // Loading state
  if (bookingsLoading) {
    return (
      <div className="bg-white p-6 rounded-lg border">
        <h3 className="text-lg font-semibold mb-4">Select Your Event Date</h3>
        <div className="animate-pulse">
          <div className="h-64 bg-gray-200 rounded"></div>
        </div>
      </div>
    );
  }

  // Error state
  if (bookingsError || !hallBookings) {
    return (
      <div className="bg-white p-6 rounded-lg border">
        <h3 className="text-lg font-semibold mb-4">Select Your Event Date</h3>
        <div className="text-center py-8">
          <p className="text-gray-500">Unable to load booking data</p>
        </div>
      </div>
    );
  }

  return (
    <div className="bg-white p-6 rounded-lg border">
      <h3 className="text-lg font-semibold mb-4">Select Your Event Date</h3>
      
      <div className="flex items-center gap-4 mb-4 text-xs">
        <div className="flex items-center gap-1">
          <Sun className="h-3 w-3 text-green-500" />
          <span>Morning Available</span>
        </div>
        <div className="flex items-center gap-1">
          <Moon className="h-3 w-3 text-green-500" />
          <span>Evening Available</span>
        </div>
        <div className="flex items-center gap-1">
          <X className="h-3 w-3 text-red-500" />
          <span>Booked</span>
        </div>
      </div>
      
      <Calendar
        mode="single"
        selected={selectedDate || undefined}
        onSelect={handleDateSelect}
        disabled={(date) => date < new Date() || getBookingStatus(date) === 'full'}
        className="w-full"
        classNames={{
          months: "flex flex-col sm:flex-row space-y-4 sm:space-x-4 sm:space-y-0 w-full",
          month: "space-y-4 w-full",
          table: "w-full border-collapse space-y-1",
          head_row: "flex w-full",
          head_cell: "text-muted-foreground rounded-md flex-1 font-normal text-[0.8rem]",
          row: "flex w-full mt-2",
          cell: "flex-1 text-center text-sm p-0 relative [&:has([aria-selected].day-range-end)]:rounded-r-md [&:has([aria-selected].day-outside)]:bg-accent/50 [&:has([aria-selected])]:bg-accent first:[&:has([aria-selected])]:rounded-l-md last:[&:has([aria-selected])]:rounded-r-md focus-within:relative focus-within:z-20",
        }}
        components={{
          Day: ({ date, ...props }) => (
            <button
              {...props}
              className="h-12 w-full flex flex-col items-center justify-center hover:bg-accent rounded-md transition-colors"
              disabled={getBookingStatus(date) === 'full' || date < new Date()}
              onClick={() => handleDateSelect(date)}
            >
              {renderDay(date)}
            </button>
          ),
        }}
      />
    </div>
  );
}
