import React, { useState } from 'react';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Textarea } from '@/components/ui/textarea';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger } from '@/components/ui/dialog';
import { Badge } from '@/components/ui/badge';
import { Switch } from '@/components/ui/switch';
import { Plus, Star, Reply, Trash2, Search } from 'lucide-react';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Review } from '@/types';
import { reviewService, authService } from '@/services/ServiceFactory';
import { useService, useServiceMutation } from '@/hooks/useService';
import { useToast } from '@/hooks/use-toast';

const Reviews = () => {
  const { toast } = useToast();
  const [newReply, setNewReply] = useState('');

  // Get current user using service hook
  const {
    data: currentUser,
    loading: userLoading,
    error: userError
  } = useService(() => Promise.resolve(authService.getCurrentUser()));

  // Get reviews using service hook
  const {
    data: reviews,
    loading: reviewsLoading,
    error: reviewsError,
    execute: executeReviews
  } = useService(() => {
    if (currentUser?.organizationId) {
      return Promise.resolve(reviewService.getReviewsByOrganization(currentUser.organizationId));
    }
    return Promise.resolve([]);
  }, {
    immediate: false
  });

  // Execute reviews fetch when user is loaded
  React.useEffect(() => {
    if (currentUser?.organizationId) {
      executeReviews();
    }
  }, [currentUser?.organizationId, executeReviews]);

  // Mutation hook for deleting review
  const deleteReviewMutation = useServiceMutation(
    (reviewId: string) => Promise.resolve(reviewService.delete(reviewId))
  );

  const handleReply = (reviewId: string) => {
    console.log('Replying to review:', reviewId, 'with:', newReply);
    setNewReply('');
  };

  const handleToggleReview = (reviewId: string, isEnabled: boolean) => {
    // Update review enabled status
    if (reviews) {
      const updatedReviews = reviews.map(review => 
        review.id === reviewId 
          ? { ...review, isEnabled } 
          : review
      );
      // In a real app, you would call a service method to update the review
      console.log('Updated reviews:', updatedReviews);
    }
    
    toast({
      title: 'Success',
      description: `Review ${isEnabled ? 'enabled' : 'disabled'} successfully`,
    });
  };

  const handleDeleteReview = async (reviewId: string) => {
    try {
      await deleteReviewMutation.execute(reviewId);
      // Refresh reviews after deletion
      if (currentUser?.organizationId) {
        executeReviews();
      }
      toast({
        title: 'Success',
        description: 'Review deleted successfully',
      });
    } catch (error) {
      toast({
        title: 'Error',
        description: 'Failed to delete review',
        variant: 'destructive',
      });
    }
  };

  const renderStars = (rating: number) => {
    return Array.from({ length: 5 }, (_, i) => (
      <Star
        key={i}
        className={`h-4 w-4 ${i < rating ? 'fill-yellow-400 text-yellow-400' : 'text-gray-300'}`}
      />
    ));
  };

  const getHallName = (hallId?: string) => {
    const halls: { [key: string]: string } = {
      '1': 'Crystal Palace Hall',
      '2': 'Golden Dreams Hall',
      '3': 'Elegant Manor'
    };
    return hallId ? halls[hallId] : 'General';
  };

  // Loading state
  if (userLoading || reviewsLoading) {
    return (
      <div className="space-y-6">
        <div className="animate-pulse">
          <div className="h-8 bg-gray-200 rounded w-1/4 mb-4"></div>
          <div className="space-y-4">
            {[...Array(3)].map((_, i) => (
              <div key={i} className="h-32 bg-gray-200 rounded"></div>
            ))}
          </div>
        </div>
      </div>
    );
  }

  // Error state
  if (userError || reviewsError || !currentUser || !reviews) {
    return (
      <div className="space-y-6">
        <div className="text-center py-8">
          <p className="text-gray-500">Unable to load reviews</p>
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <div>
          <h1 className="text-3xl font-bold">Reviews Management</h1>
          <p className="text-gray-600">Manage customer reviews and feedback</p>
        </div>
        <div className="flex items-center space-x-2">
          <Badge variant="outline">
            Total Reviews: {reviews.length}
          </Badge>
          <Badge variant="outline">
            Average Rating: {reviews.length > 0 ? (reviews.reduce((acc, r) => acc + r.rating, 0) / reviews.length).toFixed(1) : '0.0'}
          </Badge>
        </div>
      </div>

      <div className="space-y-4">
        {reviews.map((review) => (
          <Card key={review.id}>
            <CardHeader>
              <div className="flex justify-between items-start">
                <div>
                  <CardTitle className="text-lg">{review.customerName}</CardTitle>
                  <CardDescription>
                    {getHallName(review.hallId)} • {review.date}
                  </CardDescription>
                </div>
                <div className="flex items-center space-x-1">
                  {renderStars(review.rating)}
                </div>
              </div>
            </CardHeader>
            
            <CardContent>
              <p className="text-gray-700 mb-4">{review.comment}</p>
              
              <div className="flex justify-between items-center">
                <div className="flex gap-2">
                  <Dialog>
                    <DialogTrigger asChild>
                      <Button variant="outline" size="sm">
                        <Reply className="h-4 w-4 mr-1" />
                        Reply
                      </Button>
                    </DialogTrigger>
                    <DialogContent>
                      <DialogHeader>
                        <DialogTitle>Reply to Review</DialogTitle>
                      </DialogHeader>
                      <div className="space-y-4">
                        <div>
                          <Label htmlFor="reply">Your Reply</Label>
                          <Textarea
                            id="reply"
                            value={newReply}
                            onChange={(e) => setNewReply(e.target.value)}
                            placeholder="Thank you for your feedback..."
                          />
                        </div>
                        <Button onClick={() => handleReply(review.id)} className="w-full">
                          Send Reply
                        </Button>
                      </div>
                    </DialogContent>
                  </Dialog>
                  
                  <Button 
                    variant="destructive" 
                    size="sm"
                    onClick={() => handleDeleteReview(review.id)}
                    disabled={deleteReviewMutation.loading}
                  >
                    <Trash2 className="h-4 w-4 mr-1" />
                    {deleteReviewMutation.loading ? 'Deleting...' : 'Delete'}
                  </Button>
                </div>

                <div className="flex items-center space-x-2">
                  <Label htmlFor={`enable-${review.id}`} className="text-sm">
                    Show on Landing Page
                  </Label>
                  <Switch
                    id={`enable-${review.id}`}
                    checked={review.isEnabled ?? true}
                    onCheckedChange={(checked) => handleToggleReview(review.id, checked)}
                  />
                </div>
              </div>
            </CardContent>
          </Card>
        ))}
      </div>
    </div>
  );
};

export default Reviews;
