import React from 'react';
import {
  Carousel,
  CarouselContent,
  CarouselItem,
  CarouselNext,
  CarouselPrevious,
} from '@/components/ui/carousel';
import { carouselService, organizationService } from '@/services/ServiceFactory';
import { useService } from '@/hooks/useService';

export function HomeCarousel() {
  // Get current organization using service hook
  const {
    data: organization,
    loading: orgLoading,
    error: orgError
  } = useService(() => Promise.resolve(organizationService.getCurrentOrganization()));

  // Get carousel items using service hook
  const {
    data: carouselItems,
    loading: carouselLoading,
    error: carouselError,
    execute: executeCarousel
  } = useService(() => {
    if (organization?.id) {
      return Promise.resolve(carouselService.getCarouselItems(organization.id));
    }
    return Promise.resolve([]);
  }, {
    immediate: false
  });

  // Execute data fetching when organization is loaded
  React.useEffect(() => {
    if (organization?.id) {
      executeCarousel();
    }
  }, [organization?.id, executeCarousel]);

  // Loading state
  if (orgLoading || carouselLoading) {
    return (
      <div className="relative mb-12">
        <div className="animate-pulse">
          <div className="h-96 md:h-[500px] lg:h-[600px] bg-gray-200 rounded"></div>
        </div>
      </div>
    );
  }

  // Error state
  if (orgError || carouselError) {
    return null; // Don't show carousel on error
  }

  // If no organization or no carousel items, don't show carousel
  if (!organization || !carouselItems || carouselItems.length === 0) {
    return null;
  }

  return (
    <div className="relative mb-12">
      <Carousel className="w-full">
        <CarouselContent>
          {carouselItems.map((item) => (
            <CarouselItem key={item.id}>
              <div className="relative h-96 md:h-[500px] lg:h-[600px]">
                <img
                  src={`https://images.unsplash.com/${item.imageUrl}?auto=format&fit=crop&w=1920&q=80`}
                  alt={item.title}
                  className="w-full h-full object-cover rounded-lg"
                />
                <div className="absolute inset-0 bg-black/40 rounded-lg flex items-center justify-center">
                  <div className="text-center text-white max-w-2xl px-4">
                    <h1 className="text-3xl md:text-5xl lg:text-6xl font-bold mb-4">
                      {item.title}
                    </h1>
                    <p className="text-lg md:text-xl lg:text-2xl opacity-90">
                      {item.description}
                    </p>
                  </div>
                </div>
              </div>
            </CarouselItem>
          ))}
        </CarouselContent>
        <CarouselPrevious className="left-4" />
        <CarouselNext className="right-4" />
      </Carousel>
    </div>
  );
}
