import React from 'react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { MapPin, Users, Clock } from 'lucide-react';
import { hallService, organizationService } from '@/services/ServiceFactory';
import { useService } from '@/hooks/useService';

export function HallsSection() {
  // Get current organization using service hook
  const {
    data: organization,
    loading: orgLoading,
    error: orgError
  } = useService(() => Promise.resolve(organizationService.getCurrentOrganization()));

  // Get halls using service hook
  const {
    data: halls,
    loading: hallsLoading,
    error: hallsError
  } = useService(() => Promise.resolve(hallService.getAllHalls()));

  // Loading state
  if (orgLoading || hallsLoading) {
    return (
      <section className="py-12 bg-white">
        <div className="container mx-auto px-4">
          <div className="animate-pulse">
            <div className="h-8 bg-gray-200 rounded w-1/4 mb-8"></div>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {[...Array(3)].map((_, i) => (
                <div key={i} className="h-64 bg-gray-200 rounded"></div>
              ))}
            </div>
          </div>
        </div>
      </section>
    );
  }

  // Error state
  if (orgError || hallsError || !organization || !halls) {
    return null;
  }

  return (
    <section className="py-12 bg-white">
      <div className="container mx-auto px-4">
        <div className="text-center mb-12">
          <h2 className="text-4xl font-bold text-gray-900 mb-4">Our Wedding Halls</h2>
          <p className="text-xl text-gray-600 max-w-3xl mx-auto">
            Discover our beautiful venues perfect for your special day
          </p>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
          {halls.map((hall) => (
            <Card key={hall.id} className="overflow-hidden hover:shadow-lg transition-shadow">
              <div className="aspect-video relative">
                <img
                  src={hall.gallery[0] ? `https://images.unsplash.com/${hall.gallery[0]}?auto=format&fit=crop&w=400&q=80` : "/placeholder.svg"}
                  alt={hall.name}
                  className="w-full h-full object-cover"
                />
                <Badge className="absolute top-2 right-2" variant="secondary">
                  Wedding Hall
                </Badge>
              </div>

              <CardHeader>
                <CardTitle className="flex items-center justify-between">
                  {hall.name}
                  <span className="text-lg font-bold text-primary">
                    ₹{hall.rateCard.morningRate.toLocaleString()}+
                  </span>
                </CardTitle>
                <div className="flex items-center text-gray-600 text-sm">
                  <MapPin className="h-4 w-4 mr-1" />
                  {hall.location}
                </div>
              </CardHeader>

              <CardContent className="space-y-4">
                <div className="flex items-center justify-between text-sm">
                  <div className="flex items-center">
                    <Users className="h-4 w-4 mr-1" />
                    Up to {hall.capacity} guests
                  </div>
                  <div className="flex items-center">
                    <Clock className="h-4 w-4 mr-1" />
                    {hall.features.length} amenities
                  </div>
                </div>

                <p className="text-gray-600 text-sm line-clamp-2">
                  Beautiful venue located at {hall.address} with premium facilities and excellent service.
                </p>

                <div className="flex flex-wrap gap-1">
                  {hall.features.slice(0, 3).map((feature) => (
                    <Badge key={feature.name} variant="outline" className="text-xs">
                      {feature.name}
                    </Badge>
                  ))}
                  {hall.features.length > 3 && (
                    <Badge variant="outline" className="text-xs">
                      +{hall.features.length - 3} more
                    </Badge>
                  )}
                </div>

                <Button className="w-full">
                  View Details
                </Button>
              </CardContent>
            </Card>
          ))}
        </div>
      </div>
    </section>
  );
}
