import React from 'react';
import {
  Carousel,
  CarouselContent,
  CarouselItem,
  CarouselNext,
  CarouselPrevious,
} from '@/components/ui/carousel';
import { carouselService, galleryService, organizationService } from '@/services/ServiceFactory';
import { useService } from '@/hooks/useService';

export function PublicHomeCarousel() {
  // Get current organization using service hook
  const {
    data: organization,
    loading: orgLoading,
    error: orgError
  } = useService(() => Promise.resolve(organizationService.getCurrentOrganization()));

  // Get carousel items using service hook
  const {
    data: carouselItems,
    loading: carouselLoading,
    error: carouselError,
    execute: executeCarousel
  } = useService(() => {
    if (organization?.id) {
      return Promise.resolve(carouselService.getCarouselItems(organization.id));
    }
    return Promise.resolve([]);
  }, {
    immediate: false
  });

  // Get gallery images using service hook
  const {
    data: galleryImages,
    loading: galleryLoading,
    error: galleryError,
    execute: executeGallery
  } = useService(() => {
    if (organization?.id) {
      return Promise.resolve(galleryService.getImagesByOrganization(organization.id));
    }
    return Promise.resolve([]);
  }, {
    immediate: false
  });

  // Execute data fetching when organization is loaded
  React.useEffect(() => {
    if (organization?.id) {
      executeCarousel();
      executeGallery();
    }
  }, [organization?.id, executeCarousel, executeGallery]);

  // Loading state
  if (orgLoading || carouselLoading || galleryLoading) {
    return (
      <div className="relative mb-12">
        <div className="animate-pulse">
          <div className="h-96 md:h-[500px] lg:h-[600px] bg-gray-200 rounded"></div>
        </div>
      </div>
    );
  }

  // Error state
  if (orgError || carouselError || galleryError) {
    return null; // Don't show carousel on error
  }

  // If no organization, don't show carousel
  if (!organization) {
    return null;
  }

  // If no carousel items, use gallery images
  const displayItems = (carouselItems && carouselItems.length > 0) ? carouselItems : 
    (galleryImages ? galleryImages.slice(0, 5).map((img, index) => ({
      id: img.id,
      organizationId: img.organizationId,
      imageUrl: img.url,
      title: img.title,
      description: `Beautiful ${img.category}`,
      order: index + 1,
      isActive: true
    })) : []);

  if (displayItems.length === 0) return null;

  return (
    <div className="relative mb-12">
      <Carousel className="w-full">
        <CarouselContent>
          {displayItems.map((item) => (
            <CarouselItem key={item.id}>
              <div className="relative h-96 md:h-[500px] lg:h-[600px]">
                <img
                  src={item.imageUrl.includes('unsplash.com') 
                    ? `${item.imageUrl}?auto=format&fit=crop&w=1920&q=80`
                    : `${item.imageUrl}?auto=format&fit=crop&w=1920&q=80`
                  }
                  alt={item.title}
                  className="w-full h-full object-cover"
                />
                <div className="absolute inset-0 bg-black/40 flex items-center justify-center">
                  <div className="text-center text-white max-w-2xl px-4">
                    <h1 className="text-3xl md:text-5xl lg:text-6xl font-bold mb-4">
                      {item.title}
                    </h1>
                    <p className="text-lg md:text-xl lg:text-2xl opacity-90">
                      {item.description}
                    </p>
                  </div>
                </div>
              </div>
            </CarouselItem>
          ))}
        </CarouselContent>
        <CarouselPrevious className="left-4" />
        <CarouselNext className="right-4" />
      </Carousel>
    </div>
  );
}
