import React, { useState, useEffect } from 'react';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Textarea } from '@/components/ui/textarea';
import { Badge } from '@/components/ui/badge';
import { Plus, Edit, Trash2, ArrowUp, ArrowDown, Eye, EyeOff } from 'lucide-react';
import { carouselService, authService } from '@/services/ServiceFactory';
import { useToast } from '@/hooks/use-toast';
import { useService } from '@/hooks/useService';
import { CarouselItem } from '@/types';

const availableImages = [
  'photo-1649972904349-6e44c42644a7',
  'photo-1581091226825-a6a2a5aee158',
  'photo-1526374965328-7f61d4dc18c5',
  'photo-1461749280684-dccba630e2f6',
  'photo-1500673922987-e212871fec22',
  'photo-1466442929976-97f336a657be',
  'photo-1517022812141-23620dba5c23',
  'photo-1433086966358-54859d0ed716'
];

const Carousel = () => {
  const { toast } = useToast();
  
  // Get current user using service hook
  const {
    data: currentUser,
    loading: userLoading,
    error: userError
  } = useService(() => Promise.resolve(authService.getCurrentUser()));

  // Get carousel items using service hook
  const {
    data: carouselItems,
    loading: carouselLoading,
    error: carouselError,
    refresh: refreshCarouselItems
  } = useService(() => {
    if (currentUser?.organizationId) {
      return Promise.resolve(carouselService.getCarouselItems(currentUser.organizationId));
    }
    return Promise.resolve([]);
  }, {
    immediate: !!currentUser?.organizationId
  });

  const [showForm, setShowForm] = useState(false);
  const [selectedImage, setSelectedImage] = useState(availableImages[0]);
  const [title, setTitle] = useState('');
  const [description, setDescription] = useState('');
  const [editingId, setEditingId] = useState<string | null>(null);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    
    if (!currentUser) {
      toast({ 
        title: 'Error', 
        description: 'User not authenticated',
        variant: 'destructive'
      });
      return;
    }

    if (!title.trim() || !description.trim()) {
      toast({ 
        title: 'Error', 
        description: 'Title and description are required',
        variant: 'destructive'
      });
      return;
    }

    try {
      if (editingId) {
        console.log('Updating carousel item:', editingId);
        (carouselService as any).updateCarouselItem(editingId, {
          imageUrl: selectedImage,
          title: title.trim(),
          description: description.trim()
        });
        toast({ title: 'Carousel item updated successfully' });
      } else {
        console.log('Creating new carousel item');
        (carouselService as any).createCarouselItem({
          organizationId: currentUser.organizationId,
          imageUrl: selectedImage,
          title: title.trim(),
          description: description.trim(),
          order: (carouselItems?.length || 0) + 1,
          isActive: true
        });
        toast({ title: 'Carousel item created successfully' });
      }
      
      resetForm();
      refreshCarouselItems();
    } catch (error) {
      console.error('Error saving carousel item:', error);
      toast({ 
        title: 'Error', 
        description: editingId ? 'Failed to update carousel item' : 'Failed to create carousel item',
        variant: 'destructive'
      });
    }
  };

  const resetForm = () => {
    setShowForm(false);
    setTitle('');
    setDescription('');
    setSelectedImage(availableImages[0]);
    setEditingId(null);
  };

  const handleEdit = (item: CarouselItem) => {
    console.log('Editing carousel item:', item);
    setEditingId(item.id);
    setTitle(item.title);
    setDescription(item.description);
    setSelectedImage(item.imageUrl);
    setShowForm(true);
  };

  const handleDelete = (id: string) => {
    console.log('Deleting carousel item:', id);
    try {
      const success = (carouselService as any).deleteCarouselItem(id);
      if (success) {
        refreshCarouselItems();
        toast({ title: 'Carousel item deleted successfully' });
      } else {
        throw new Error('Failed to delete item');
      }
    } catch (error) {
      console.error('Error deleting carousel item:', error);
      toast({ 
        title: 'Error', 
        description: 'Failed to delete carousel item',
        variant: 'destructive'
      });
    }
  };

  const handleMoveUp = (id: string) => {
    if (!currentUser) return;
    
    console.log('Moving item up:', id);
    try {
      const success = (carouselService as any).moveItemUp(id, currentUser.organizationId);
      if (success) {
        refreshCarouselItems();
        toast({ title: 'Position updated successfully' });
      } else {
        toast({ 
          title: 'Info', 
          description: 'Item is already at the top',
          variant: 'default'
        });
      }
    } catch (error) {
      console.error('Error moving item up:', error);
      toast({ 
        title: 'Error', 
        description: 'Failed to update position',
        variant: 'destructive'
      });
    }
  };

  const handleMoveDown = (id: string) => {
    if (!currentUser) return;
    
    console.log('Moving item down:', id);
    try {
      const success = (carouselService as any).moveItemDown(id, currentUser.organizationId);
      if (success) {
        refreshCarouselItems();
        toast({ title: 'Position updated successfully' });
      } else {
        toast({ 
          title: 'Info', 
          description: 'Item is already at the bottom',
          variant: 'default'
        });
      }
    } catch (error) {
      console.error('Error moving item down:', error);
      toast({ 
        title: 'Error', 
        description: 'Failed to update position',
        variant: 'destructive'
      });
    }
  };

  const handleToggleStatus = (id: string) => {
    console.log('Toggling status for item:', id);
    try {
      (carouselService as any).toggleItemStatus(id);
      refreshCarouselItems();
      toast({ title: 'Item status updated successfully' });
    } catch (error) {
      console.error('Error toggling item status:', error);
      toast({ 
        title: 'Error', 
        description: 'Failed to update item status',
        variant: 'destructive'
      });
    }
  };

  // Show loading state
  if (userLoading || carouselLoading) {
    return <div>Loading...</div>;
  }

  // Show error state
  if (userError || carouselError) {
    return <div>Error loading data</div>;
  }

  const items = carouselItems || [];

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <div>
          <h1 className="text-3xl font-bold">Carousel Management</h1>
          <p className="text-gray-600">Manage your homepage carousel images and content</p>
        </div>
        <Button onClick={() => setShowForm(!showForm)}>
          <Plus className="h-4 w-4 mr-2" />
          Add Carousel Item
        </Button>
      </div>

      {showForm && (
        <Card>
          <CardHeader>
            <CardTitle>{editingId ? 'Edit' : 'Add'} Carousel Item</CardTitle>
            <CardDescription>
              Select an image from the gallery and add title and description
            </CardDescription>
          </CardHeader>
          <CardContent>
            <form onSubmit={handleSubmit} className="space-y-4">
              <div>
                <Label>Select Image</Label>
                <div className="grid grid-cols-2 md:grid-cols-4 gap-3 mt-2">
                  {availableImages.map((image) => (
                    <div
                      key={image}
                      className={`relative cursor-pointer rounded-lg overflow-hidden border-2 ${
                        selectedImage === image ? 'border-primary' : 'border-gray-200'
                      }`}
                      onClick={() => setSelectedImage(image)}
                    >
                      <img
                        src={`https://images.unsplash.com/${image}?auto=format&fit=crop&w=200&q=80`}
                        alt="Gallery option"
                        className="w-full h-24 object-cover"
                      />
                      {selectedImage === image && (
                        <div className="absolute inset-0 bg-primary/20 flex items-center justify-center">
                          <Badge>Selected</Badge>
                        </div>
                      )}
                    </div>
                  ))}
                </div>
              </div>

              <div>
                <Label htmlFor="title">Title</Label>
                <Input
                  id="title"
                  value={title}
                  onChange={(e) => setTitle(e.target.value)}
                  required
                  placeholder="Enter carousel item title"
                />
              </div>

              <div>
                <Label htmlFor="description">Description</Label>
                <Textarea
                  id="description"
                  value={description}
                  onChange={(e) => setDescription(e.target.value)}
                  required
                  placeholder="Enter carousel item description"
                />
              </div>

              <div className="flex gap-2">
                <Button type="submit">
                  {editingId ? 'Update' : 'Create'} Item
                </Button>
                <Button type="button" variant="outline" onClick={resetForm}>
                  Cancel
                </Button>
              </div>
            </form>
          </CardContent>
        </Card>
      )}

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {items.map((item) => (
          <Card key={item.id}>
            <div className="relative h-48">
              <img
                src={`https://images.unsplash.com/${item.imageUrl}?auto=format&fit=crop&w=400&q=80`}
                alt={item.title}
                className="w-full h-full object-cover"
              />
              <Badge className="absolute top-2 right-2">
                Order: {item.order}
              </Badge>
              
              <div className="absolute top-2 left-2 flex flex-col gap-1">
                <Button
                  size="sm"
                  variant="outline"
                  className="h-8 w-8 p-0 bg-white/80"
                  onClick={() => handleMoveUp(item.id)}
                  disabled={item.order <= 1}
                >
                  <ArrowUp className="h-4 w-4" />
                </Button>
                <Button
                  size="sm"
                  variant="outline"
                  className="h-8 w-8 p-0 bg-white/80"
                  onClick={() => handleMoveDown(item.id)}
                  disabled={item.order >= items.length}
                >
                  <ArrowDown className="h-4 w-4" />
                </Button>
              </div>
            </div>
            
            <CardHeader>
              <CardTitle className="text-lg">{item.title}</CardTitle>
              <CardDescription>{item.description}</CardDescription>
            </CardHeader>
            
            <CardContent>
              <div className="flex justify-between items-center">
                <Badge variant={item.isActive ? 'default' : 'secondary'}>
                  {item.isActive ? 'Active' : 'Inactive'}
                </Badge>
                
                <div className="flex gap-2">
                  <Button
                    size="sm"
                    variant="outline"
                    onClick={() => handleToggleStatus(item.id)}
                  >
                    {item.isActive ? (
                      <EyeOff className="h-4 w-4" />
                    ) : (
                      <Eye className="h-4 w-4" />
                    )}
                  </Button>
                  <Button
                    size="sm"
                    variant="outline"
                    onClick={() => handleEdit(item)}
                  >
                    <Edit className="h-4 w-4" />
                  </Button>
                  <Button
                    size="sm"
                    variant="destructive"
                    onClick={() => handleDelete(item.id)}
                  >
                    <Trash2 className="h-4 w-4" />
                  </Button>
                </div>
              </div>
            </CardContent>
          </Card>
        ))}
      </div>

      {items.length === 0 && (
        <Card>
          <CardContent className="text-center py-8">
            <div className="text-gray-500">
              <h3 className="text-lg font-medium mb-2">No carousel items</h3>
              <p>Create your first carousel item to get started.</p>
            </div>
          </CardContent>
        </Card>
      )}
    </div>
  );
};

export default Carousel;
