import { IUserService } from '../interfaces/IDataService';
import { User } from '../../types';
import { apiClient } from '../http/ApiClient';

export class ApiUserService implements IUserService {
  async getAll(): Promise<User[]> {
    return apiClient.get<User[]>('/api/users');
  }

  async getById(id: string): Promise<User | null> {
    try {
      return await apiClient.get<User>(`/api/users/${id}`);
    } catch (error) {
      if (error.status === 404) {
        return null;
      }
      throw error;
    }
  }

  async create(data: Omit<User, 'id'>): Promise<User> {
    return apiClient.post<User>('/api/users', data);
  }

  async update(id: string, data: Partial<User>): Promise<User> {
    return apiClient.put<User>(`/api/users/${id}`, data);
  }

  async delete(id: string): Promise<boolean> {
    try {
      await apiClient.delete(`/api/users/${id}`);
      return true;
    } catch (error) {
      return false;
    }
  }

  async getUsersByOrganization(organizationId: string): Promise<User[]> {
    return apiClient.get<User[]>(`/api/organizations/${organizationId}/users`);
  }
} 