import React, { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Textarea } from '@/components/ui/textarea';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { ArrowLeft } from 'lucide-react';
import { bookingService, hallService } from '@/services/ServiceFactory';
import { useToast } from '@/hooks/use-toast';
import { useService } from '@/hooks/useService';
import { Booking } from '@/types';

const BookingEdit = () => {
  const { bookingId } = useParams<{ bookingId: string }>();
  const navigate = useNavigate();
  const { toast } = useToast();
  
  // Use service hooks for async data fetching
  const {
    data: bookings,
    loading: bookingsLoading,
    error: bookingsError
  } = useService(() => bookingService.getBookingsByOrganization('1'));
  
  const booking = bookings?.find(b => b.id === bookingId);
  
  // State initialization with proper type safety
  const [customerName, setCustomerName] = useState<string>('');
  const [customerEmail, setCustomerEmail] = useState<string>('');
  const [customerPhone, setCustomerPhone] = useState<string>('');
  const [eventDate, setEventDate] = useState<string>('');
  const [eventType, setEventType] = useState<string>('');
  const [timeSlot, setTimeSlot] = useState<Booking['timeSlot']>('morning');
  const [guestCount, setGuestCount] = useState<string>('');
  const [status, setStatus] = useState<Booking['status']>('pending');
  const [statusReason, setStatusReason] = useState<string>('');
  const [lastContactDate, setLastContactDate] = useState<string>('');
  const [customerResponse, setCustomerResponse] = useState<string>('');
  const [loading, setLoading] = useState<boolean>(false);

  // Get hall data using the correct service method
  const {
    data: hall,
    loading: hallLoading,
    error: hallError
  } = useService(() => {
    if (booking?.hallId) {
      return hallService.getById(booking.hallId);
    }
    return Promise.resolve(null);
  }, {
    immediate: !!booking?.hallId
  });

  // Update form state when booking data is loaded
  useEffect(() => {
    if (booking) {
      setCustomerName(booking.customerName || '');
      setCustomerEmail(booking.customerEmail || '');
      setCustomerPhone(booking.customerPhone || '');
      setEventDate(booking.eventDate || '');
      setEventType(booking.eventType || '');
      setTimeSlot(booking.timeSlot || 'morning');
      setGuestCount(booking.guestCount?.toString() || '');
      setStatus(booking.status || 'pending');
      setLastContactDate(booking.lastContactDate || '');
      setCustomerResponse(booking.customerResponse || '');
    }
  }, [booking]);

  // Show loading state
  if (bookingsLoading) {
    return <div>Loading booking details...</div>;
  }

  // Show error state - fix the error access
  if (bookingsError) {
    return <div>Error loading booking: {bookingsError}</div>;
  }

  // Show not found state
  if (!booking) {
    return <div>Booking not found</div>;
  }

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);

    try {
      // Update booking status if changed
      if (status !== booking.status) {
        await bookingService.updateBookingStatus(booking.id, status, statusReason);
      }
      
      // Update communication if provided
      if (lastContactDate || customerResponse) {
        await bookingService.updateBookingCommunication(booking.id, lastContactDate, customerResponse);
      }
      
      toast({
        title: 'Success',
        description: 'Booking updated successfully!',
      });
      
      navigate('/admin/bookings');
    } catch (error) {
      console.error('Error updating booking:', error);
      toast({
        title: 'Error',
        description: 'Failed to update booking',
        variant: 'destructive',
      });
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <Button 
          variant="outline" 
          onClick={() => navigate('/admin/bookings')}
        >
          <ArrowLeft className="h-4 w-4 mr-2" />
          Back to Bookings
        </Button>
        <h1 className="text-2xl font-bold">Edit Booking</h1>
      </div>

      <form onSubmit={handleSubmit} className="space-y-6">
        <Card>
          <CardHeader>
            <CardTitle>Customer Information</CardTitle>
          </CardHeader>
          <CardContent className="space-y-4">
            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-2">
                <Label htmlFor="customerName">Customer Name</Label>
                <Input
                  id="customerName"
                  value={customerName}
                  onChange={(e) => setCustomerName(e.target.value)}
                  required
                  disabled
                />
              </div>
              
              <div className="space-y-2">
                <Label htmlFor="customerEmail">Email</Label>
                <Input
                  id="customerEmail"
                  type="email"
                  value={customerEmail}
                  onChange={(e) => setCustomerEmail(e.target.value)}
                  required
                  disabled
                />
              </div>
            </div>
            
            <div className="space-y-2">
              <Label htmlFor="customerPhone">Phone</Label>
              <Input
                id="customerPhone"
                value={customerPhone}
                onChange={(e) => setCustomerPhone(e.target.value)}
                required
                disabled
              />
            </div>
          </CardContent>
        </Card>

        <Card>
          <CardHeader>
            <CardTitle>Event Details</CardTitle>
          </CardHeader>
          <CardContent className="space-y-4">
            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-2">
                <Label htmlFor="hall">Hall</Label>
                <Input
                  id="hall"
                  value={hall?.name || 'Loading...'}
                  disabled
                />
              </div>
              
              <div className="space-y-2">
                <Label htmlFor="eventDate">Event Date</Label>
                <Input
                  id="eventDate"
                  type="date"
                  value={eventDate}
                  onChange={(e) => setEventDate(e.target.value)}
                  required
                  disabled
                />
              </div>
            </div>
            
            <div className="grid grid-cols-3 gap-4">
              <div className="space-y-2">
                <Label htmlFor="eventType">Event Type</Label>
                <Input
                  id="eventType"
                  value={eventType}
                  onChange={(e) => setEventType(e.target.value)}
                  required
                  disabled
                />
              </div>
              
              <div className="space-y-2">
                <Label htmlFor="timeSlot">Time Slot</Label>
                <Input
                  id="timeSlot"
                  value={timeSlot}
                  disabled
                />
              </div>
              
              <div className="space-y-2">
                <Label htmlFor="guestCount">Guest Count</Label>
                <Input
                  id="guestCount"
                  type="number"
                  value={guestCount}
                  onChange={(e) => setGuestCount(e.target.value)}
                  required
                  disabled
                />
              </div>
            </div>
          </CardContent>
        </Card>

        <Card>
          <CardHeader>
            <CardTitle>Status Management</CardTitle>
          </CardHeader>
          <CardContent className="space-y-4">
            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-2">
                <Label htmlFor="status">Status</Label>
                <Select value={status} onValueChange={(value) => setStatus(value as Booking['status'])}>
                  <SelectTrigger>
                    <SelectValue placeholder="Select status" />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="pending">Pending</SelectItem>
                    <SelectItem value="confirmed">Confirmed</SelectItem>
                    <SelectItem value="cancelled">Cancelled</SelectItem>
                    <SelectItem value="active">Active</SelectItem>
                    <SelectItem value="completed">Completed</SelectItem>
                  </SelectContent>
                </Select>
              </div>
            </div>
            
            {status !== booking.status && (
              <div className="space-y-2">
                <Label htmlFor="statusReason">Reason for Status Change</Label>
                <Textarea
                  id="statusReason"
                  value={statusReason}
                  onChange={(e) => setStatusReason(e.target.value)}
                  placeholder="Enter reason for status change..."
                  rows={3}
                />
              </div>
            )}
          </CardContent>
        </Card>

        <Card>
          <CardHeader>
            <CardTitle>Communication Log</CardTitle>
          </CardHeader>
          <CardContent className="space-y-4">
            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-2">
                <Label htmlFor="lastContactDate">Last Contact Date</Label>
                <Input
                  id="lastContactDate"
                  type="date"
                  value={lastContactDate}
                  onChange={(e) => setLastContactDate(e.target.value)}
                />
              </div>
            </div>
            
            <div className="space-y-2">
              <Label htmlFor="customerResponse">Customer Response</Label>
              <Textarea
                id="customerResponse"
                value={customerResponse}
                onChange={(e) => setCustomerResponse(e.target.value)}
                placeholder="Enter customer response or communication notes..."
                rows={4}
              />
            </div>
          </CardContent>
        </Card>
        
        <div className="flex justify-end space-x-4">
          <Button type="button" variant="outline" onClick={() => navigate('/admin/bookings')}>
            Cancel
          </Button>
          <Button type="submit" disabled={loading}>
            {loading ? 'Updating...' : 'Update Booking'}
          </Button>
        </div>
      </form>
    </div>
  );
};

export default BookingEdit;
