
import React from 'react';
import { Card, CardContent } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Star } from 'lucide-react';
import { format } from 'date-fns';

interface Review {
  id: string;
  customerName: string;
  reviewDate: string;
  hallDate: string;
  eventDate: string;
  rating: number;
  comment: string;
}

interface HallDetailReviewsProps {
  hallId: string;
}

// Mock reviews data - in a real app this would come from a service
const mockReviews: Review[] = [
  {
    id: '1',
    customerName: 'Rajesh Kumar',
    reviewDate: '2024-01-15',
    hallDate: '2024-01-10',
    eventDate: '2024-01-12',
    rating: 5,
    comment: 'Excellent service and beautiful venue. The staff was very helpful and professional. Highly recommended!'
  },
  {
    id: '2',
    customerName: 'Priya Sharma',
    reviewDate: '2024-01-20',
    hallDate: '2024-01-15',
    eventDate: '2024-01-18',
    rating: 4,
    comment: 'Great hall with good amenities. The decorations were amazing and the food quality was excellent.'
  },
  {
    id: '3',
    customerName: 'Amit Singh',
    reviewDate: '2024-01-25',
    hallDate: '2024-01-20',
    eventDate: '2024-01-22',
    rating: 5,
    comment: 'Perfect venue for our wedding. The management was very cooperative and everything was well organized.'
  }
];

export function HallDetailReviews({ hallId }: HallDetailReviewsProps) {
  // Filter reviews for this hall (in real app, this would be based on actual hall bookings)
  const hallReviews = mockReviews;

  const renderStars = (rating: number) => {
    return Array.from({ length: 5 }, (_, i) => (
      <Star
        key={i}
        className={`h-4 w-4 ${i < rating ? 'fill-yellow-400 text-yellow-400' : 'text-gray-300'}`}
      />
    ));
  };

  return (
    <div className="space-y-4">
      <h3 className="text-xl font-semibold">Customer Reviews</h3>
      
      {hallReviews.length === 0 ? (
        <p className="text-gray-500">No reviews yet for this hall.</p>
      ) : (
        <div className="space-y-4">
          {hallReviews.map((review) => (
            <Card key={review.id}>
              <CardContent className="p-4">
                <div className="flex justify-between items-start">
                  <div className="flex-1">
                    <div className="flex items-center gap-2 mb-2">
                      <h4 className="font-semibold">{review.customerName}</h4>
                      <Badge variant="outline" className="text-xs">
                        {format(new Date(review.reviewDate), 'MMM dd, yyyy')}
                      </Badge>
                    </div>
                    <div className="flex items-center gap-2 mb-2">
                      <div className="flex">{renderStars(review.rating)}</div>
                      <span className="text-sm text-gray-600">({review.rating}/5)</span>
                    </div>
                    <p className="text-gray-700 text-sm">{review.comment}</p>
                  </div>
                  
                  <div className="ml-4 text-right">
                    <div className="text-xs text-gray-500">Hall Booking</div>
                    <div className="text-sm font-medium">
                      {format(new Date(review.hallDate), 'MMM dd')}
                    </div>
                    <div className="text-xs text-gray-500 mt-1">Event Date</div>
                    <div className="text-sm font-medium">
                      {format(new Date(review.eventDate), 'MMM dd')}
                    </div>
                  </div>
                </div>
              </CardContent>
            </Card>
          ))}
        </div>
      )}
    </div>
  );
}
