
import React from 'react';
import { Card, CardContent } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';

interface ComponentConfig {
  slotTime?: number;
  width?: string;
  height?: string;
  maxCount?: number;
  title?: string;
  description?: string;
  imageUrl?: string;
  imagePosition?: 'left' | 'right';
  textAlignment?: 'left' | 'right';
  blockWidth?: '1/4' | '1/3' | '1/2' | 'full';
}

interface PreviewComponent {
  id: string;
  type: string;
  order: number;
  isActive: boolean;
  config?: ComponentConfig;
}

interface MicrositePreviewProps {
  components: PreviewComponent[];
}

export function MicrositePreview({ components }: MicrositePreviewProps) {
  const getWidthClass = (width?: string) => {
    switch (width) {
      case '1/4': return 'w-1/4';
      case '1/3': return 'w-1/3';
      case '1/2': return 'w-1/2';
      default: return 'w-full';
    }
  };

  const renderComponent = (component: PreviewComponent) => {
    if (!component.isActive) return null;

    const config = component.config || {};

    switch (component.type) {
      case 'carousel':
        return (
          <div className="relative h-64 bg-gradient-to-r from-blue-500 to-purple-600 rounded-lg overflow-hidden">
            <div className="absolute inset-0 flex items-center justify-center text-white">
              <div className="text-center">
                <h2 className="text-3xl font-bold mb-2">Welcome to Our Venue</h2>
                <p className="text-lg">Make your special day unforgettable</p>
                <div className="mt-4 text-sm opacity-75">
                  Auto-advance: {config.slotTime || 5}s
                </div>
              </div>
            </div>
          </div>
        );

      case 'halls':
        return (
          <div className="space-y-4" style={{ width: config.width, height: config.height }}>
            <h2 className="text-2xl font-bold text-center">Our Wedding Halls</h2>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
              {[1, 2, 3].map((i) => (
                <Card key={i} className="overflow-hidden">
                  <div className="h-32 bg-gray-200 flex items-center justify-center">
                    <span className="text-gray-500">Hall {i}</span>
                  </div>
                  <CardContent className="p-3">
                    <h3 className="font-semibold">Grand Hall {i}</h3>
                    <p className="text-sm text-gray-600">Capacity: 500 guests</p>
                    <Badge className="mt-2">₹50,000</Badge>
                  </CardContent>
                </Card>
              ))}
            </div>
          </div>
        );

      case 'reviews':
        const maxReviews = config.maxCount || 6;
        return (
          <div className="space-y-4">
            <h2 className="text-2xl font-bold text-center">Customer Reviews</h2>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
              {Array.from({ length: Math.min(maxReviews, 6) }).map((_, i) => (
                <Card key={i}>
                  <CardContent className="p-4">
                    <div className="flex items-center mb-2">
                      <div className="flex text-yellow-500">
                        {'★'.repeat(5)}
                      </div>
                    </div>
                    <p className="text-sm text-gray-600 mb-2">
                      "Amazing venue with excellent service. Highly recommended!"
                    </p>
                    <p className="text-sm font-semibold">- Customer {i + 1}</p>
                  </CardContent>
                </Card>
              ))}
            </div>
            <p className="text-center text-sm text-gray-500">Showing {Math.min(maxReviews, 6)} reviews</p>
          </div>
        );

      case 'text':
        return (
          <div className={`${getWidthClass(config.blockWidth)} mx-auto`}>
            <div className={`flex ${config.imagePosition === 'right' ? 'flex-row-reverse' : 'flex-row'} items-center gap-6`}>
              {config.imageUrl && (
                <div className="flex-shrink-0 w-48 h-32">
                  <img 
                    src={config.imageUrl} 
                    alt={config.title} 
                    className="w-full h-full object-cover rounded-lg"
                  />
                </div>
              )}
              <div className={`flex-1 text-${config.textAlignment || 'left'}`}>
                {config.title && (
                  <h2 className="text-2xl font-bold mb-4">{config.title}</h2>
                )}
                {config.description && (
                  <p className="text-gray-600">{config.description}</p>
                )}
              </div>
            </div>
          </div>
        );

      case 'image':
        return (
          <div className="text-center">
            {config.imageUrl && (
              <img 
                src={config.imageUrl} 
                alt={config.title} 
                className="w-full max-w-2xl mx-auto rounded-lg"
              />
            )}
            {config.title && (
              <p className="mt-2 text-gray-600">{config.title}</p>
            )}
          </div>
        );

      case 'search':
        return (
          <Card>
            <CardContent className="p-6">
              <h2 className="text-2xl font-bold text-center mb-4">Find Your Perfect Hall</h2>
              <div className="flex gap-4 max-w-md mx-auto">
                <input 
                  type="text" 
                  placeholder="Search halls..." 
                  className="flex-1 px-3 py-2 border rounded-lg"
                />
                <button className="px-6 py-2 bg-blue-600 text-white rounded-lg">Search</button>
              </div>
            </CardContent>
          </Card>
        );

      default:
        return (
          <div className="p-4 border border-dashed border-gray-300 rounded-lg text-center text-gray-500">
            {component.type} component
          </div>
        );
    }
  };

  const activeComponents = components
    .filter(c => c.isActive)
    .sort((a, b) => a.order - b.order);

  return (
    <div className="space-y-8 p-6 bg-gray-50 min-h-screen">
      <div className="max-w-6xl mx-auto">
        <h1 className="text-3xl font-bold text-center mb-8">Microsite Preview</h1>
        {activeComponents.map((component) => (
          <div key={component.id} className="mb-8">
            {renderComponent(component)}
          </div>
        ))}
        {activeComponents.length === 0 && (
          <div className="text-center text-gray-500 py-12">
            No active components to display. Add some components to see the preview.
          </div>
        )}
      </div>
    </div>
  );
}
